SELECT CASE WHEN duration_sec >= 525 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, MAX(event_time) AS ended_at, COUNT(*) FILTER (WHERE event_type = 'search') AS search_rows, MAX(event_time) AS ended_at_2, GROUPING_ID() AS gid FROM web_events GROUP BY CUBE (CASE WHEN duration_sec >= 525 THEN 'LARGE' ELSE 'SMALL' END) HAVING COUNT(*) FILTER (WHERE event_type = 'search') < 1000;
